export const instructors=[
 {id:'rhea',name:'Rhea',initial:'R',description:'A new challenger. Same short fuse. Different presence.'},
 {id:'fighter',name:'Coach Vale',initial:'V',description:'The close-up confrontation. Boxing stance, no patience.'},
 {id:'professor',name:'Professor Slate',initial:'S',description:'The original professor. Cute until you push it.'},
 {id:'sergeant',name:'Sergeant Knox',initial:'K',description:'A drill sergeant with very little tolerance.'},
 {id:'midnight',name:'Unit Zero',initial:'0',description:'Cold stare. Mechanical menace.'}
];
export const volumeFor=value=>Number.isFinite(value)?Math.min(1,Math.max(0,value)):.65;
export function preferencesMarkup(settings){return `<span class="eyebrow">SET YOUR TERMS</span><h2>Choose your problem.</h2><p>Same rule. Your choice of company.</p><div class="instructor-grid" role="group" aria-label="Choose your instructor">${instructors.map(i=>`<button data-costume="${i.id}" class="instructor-card" aria-pressed="${settings.costume===i.id}"><span class="instructor-mark" aria-hidden="true">${i.initial}</span><span><b>${i.name}</b><small>${i.description}</small></span></button>`).join('')}</div>
 <div class="appearance-options"><label for="background">Your arena</label><select id="background">${[{id:'classroom',name:'Detention hall'},{id:'gym',name:'After-hours gym'},{id:'rooftop',name:'Midnight rooftop'}].map(x=>`<option value="${x.id}" ${settings.background===x.id?'selected':''}>${x.name}</option>`).join('')}</select><label for="outfit">Training outfit · Vale & Rhea</label><select id="outfit">${[{id:'original',name:'Slate'},{id:'ember',name:'Ember'},{id:'arctic',name:'Arctic'}].map(x=>`<option value="${x.id}" ${settings.outfit===x.id?'selected':''}>${x.name}</option>`).join('')}</select><small class="preference-note">Characters, outfits and arenas are separate. These starter outfits are free.</small></div>
 <p class="note"><a href="./avatar-lab.html">Open the realistic avatar workshop ↗</a></p><label for="tone">Personality</label><select id="tone"><option value="gentle">Gentle · longer fuse</option><option value="strict">Strict · judgment, then rage</option><option value="savage">Savage · swearing encouraged</option></select>
 <div class="preference-section"><label class="settings-row"><input id="sound" type="checkbox">Sound effects</label><div class="volume-heading"><label for="volume">Volume</label><output id="volume-value" for="volume">${Math.round(volumeFor(settings.volume)*100)}%</output></div><input id="volume" type="range" min="0" max="100" step="5" value="${Math.round(volumeFor(settings.volume)*100)}"><button class="sample-sound secondary" id="sample-sound">Test warning sound</button><small class="preference-note">Sound plays only when enabled. Test it before class.</small></div>
 <label class="settings-row"><input id="haptics" type="checkbox">Vibration where supported</label><label class="settings-row"><input id="motion" type="checkbox">Reduce motion</label><label class="settings-row"><input id="cracks" type="checkbox">Cracked glass at maximum rage</label><button class="primary" id="save-settings">Save preferences</button><p class="note">Camera processing stays on this device. No recordings or uploads. Progress is saved in this browser. Fonts load from Google.</p><button class="quiet-button reset-progress" id="reset">Erase local progress</button>`;}
